const sonidoPintar=new Audio('https://cdn.jsdelivr.net/gh/fhlebihan/bppdf@main/pintar.mp3');const sonidoPagina=new Audio('https://cdn.jsdelivr.net/gh/fhlebihan/bppdf@main/pagina.mp3');let isMuted=false;sonidoPintar.volume=0.4;sonidoPagina.volume=0.6;let haPintado=false;function sonar(audio){audio.currentTime=0;audio.play().catch(e=>console.log("El audio espera interacción del usuario"));}function toggleMute(){isMuted=!isMuted;const emoji=document.getElementById('mute-emoji');const btn=document.getElementById('mute-btn');sonidoPintar.muted=isMuted;sonidoPagina.muted=isMuted;if(isMuted){emoji.innerText="🔇";btn.classList.add('muted-active');}else{emoji.innerText="🔊";btn.classList.remove('muted-active');}}let canvas,ctx;let painting=false;let color=generarColorAleatorio();let tool="bucket";let brushSize=5;let currentRotationText=0;let currentFontSizeText=30;let textEditorPosition={x:0,y:0};function initCanvas(canvasId){canvas=document.getElementById(canvasId);if(!canvas)return;const container=canvas.parentElement;const resize=()=>{const tempImage=ctx ? ctx.getImageData(0,0,canvas.width,canvas.height):null;canvas.width=container.clientWidth;canvas.height=container.clientHeight;ctx=canvas.getContext("2d",{willReadFrequently:true});ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);if(tempImage)ctx.putImageData(tempImage,0,0);ctx.lineCap="round";ctx.lineJoin="round";};resize();window.addEventListener('resize',resize);canvas.addEventListener("mousedown",startPosition);canvas.addEventListener("mouseup",finishedPosition);canvas.addEventListener("mousemove",draw);canvas.addEventListener("touchstart",(e)=>{e.preventDefault();startPosition(e.touches[0]);},{passive:false});canvas.addEventListener("touchend",(e)=>{e.preventDefault();finishedPosition();},{passive:false});canvas.addEventListener("touchmove",(e)=>{e.preventDefault();draw(e.touches[0]);},{passive:false});actualizarSelectorColor();console.log("Canvas ajustado a:"+canvas.width+"x"+canvas.height);}function startPosition(e){if(pdfActual[indiceActual].toLowerCase().endsWith("(0).png")){transicionPagina('siguiente');}if(tool==="bucket"){executeFloodFill(e);return;}else if(tool==="text"){escribirTexto(e);}painting=true;draw(e);alert("va a ejecutar mostrarbot");mostrarBotonCompartir();}function finishedPosition(){painting=false;ctx.beginPath();}function draw(e){if(!painting || tool !=="brush")return;const rect=canvas.getBoundingClientRect();const scaleX=canvas.width/rect.width;const scaleY=canvas.height/rect.height;const x=(e.clientX-rect.left)*scaleX;const y=(e.clientY-rect.top)*scaleY;ctx.lineWidth=brushSize;ctx.lineCap="round";ctx.strokeStyle=color;ctx.lineTo(x,y);ctx.stroke();ctx.beginPath();ctx.moveTo(x,y);}function executeFloodFill(e){sonar(sonidoPintar);const rect=canvas.getBoundingClientRect();const scaleX=canvas.width/rect.width;const scaleY=canvas.height/rect.height;const startX=Math.floor((e.clientX-rect.left)*scaleX);const startY=Math.floor((e.clientY-rect.top)*scaleY);const imageData=ctx.getImageData(0,0,canvas.width,canvas.height);const pixelData=imageData.data;const startPos=(startY*canvas.width+startX)*4;const startR=pixelData[startPos];const startG=pixelData[startPos+1];const startB=pixelData[startPos+2];const startA=pixelData[startPos+3];const fillColor=hexToRgb(color);const tolerance=50;if(matchColor(startR,startG,startB,startA,fillColor.r,fillColor.g,fillColor.b,255,0))return;const todo=[[startX,startY]];while(todo.length>0){const[x,y]=todo.pop();const currentPos=(y*canvas.width+x)*4;if(matchColor(pixelData[currentPos],pixelData[currentPos+1],pixelData[currentPos+2],pixelData[currentPos+3],startR,startG,startB,startA,tolerance)){pixelData[currentPos]=fillColor.r;pixelData[currentPos+1]=fillColor.g;pixelData[currentPos+2]=fillColor.b;pixelData[currentPos+3]=255;if(x>0)todo.push([x-1,y]);if(x<canvas.width-1)todo.push([x+1,y]);if(y>0)todo.push([x,y-1]);if(y<canvas.height-1)todo.push([x,y+1]);}}ctx.putImageData(imageData,0,0);}function matchColor(r1,g1,b1,a1,r2,g2,b2,a2,tolerance){return Math.abs(r1-r2)<=tolerance && Math.abs(g1-g2)<=tolerance && Math.abs(b1-b2)<=tolerance && Math.abs(a1-a2)<=tolerance;}function hexToRgb(hex){const result=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);return result ?{r:parseInt(result[1],16),g:parseInt(result[2],16),b:parseInt(result[3],16)}:{r:0,g:0,b:0};}function clearCanvas(){ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);if(pdfActual && pdfActual[indiceActual]){cargarDibujo(pdfActual[indiceActual]);}console.log("Progreso reiniciado para el dibujo:",pdfActual[indiceActual]);}function downloadImage(){const link=document.createElement("a");link.download="mi-dibujo-creativo.png";link.href=canvas.toDataURL("image/png");link.click();}async function shareImage(){const dataUrl=canvas.toDataURL("image/png");const blob=await(await fetch(dataUrl)).blob();const file=new File([blob],'dibujo.png',{type:'image/png'});if(navigator.share){try{await navigator.share({files:[file],title:'Mira mi dibujo',text:'¡Mira lo que pinté en mi App de Arte!'});}catch(err){console.log("Error al compartir:",err);}}else{alert("Tu navegador no soporta la función compartir. ¡Usa el botón de Guardar!");}}function cargarDibujo(url){const img=new Image();img.crossOrigin="anonymous";let urlSegura=url.replace("blogger.googleusercontent.com/img/b/","lh3.googleusercontent.com/d/");const conector=urlSegura.includes('?')? '&':'?';img.src=urlSegura+conector+"cache_bust="+Date.now();img.onload=()=>{ctx.globalCompositeOperation="source-over";ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);const escala=Math.min(canvas.width/img.width,canvas.height/img.height);const anchoFinal=img.width*escala;const altoFinal=img.height*escala;const x=(canvas.width/2)-(anchoFinal/2);const y=(canvas.height/2)-(altoFinal/2);ctx.drawImage(img,x,y,anchoFinal,altoFinal);console.log("Éxito:Dibujo cargado y procesable para pintura.");};img.onerror=()=>{console.error("Error crítico:No se pudo cargar la imagen desde la URL proporcionada.");};}function generarColorAleatorio(){const randomColor="#"+Math.floor(Math.random()*16777215).toString(16).padStart(6,'0');return randomColor;}function actualizarSelectorColor(){const picker=document.getElementById('colorPicker');if(picker){picker.value=color;picker.parentElement.style.borderBottom=`4px solid ${color}`;}}async function shareImage(){const dataUrl=canvas.toDataURL("image/png");const blob=await(await fetch(dataUrl)).blob();const file=new File([blob],'mi-dibujo.png',{type:'image/png'});if(navigator.canShare && navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:'¡Mira mi dibujo!',text:'He coloreado este dibujo en mi app de arte.'});}catch(err){console.error("Error al compartir:",err);}}else{alert("Tu navegador no soporta compartir directamente. Descargando imagen...");downloadImage();}}function anteriorDibujo(){if(pdfActual.length===0)return;indiceActual=(indiceActual-1+pdfActual.length)% pdfActual.length;cargarDibujo(pdfActual[indiceActual]);}function escribirTexto(e){mostrarEditorTexto(e);}function actualizarCursor(){const canvasElement=document.getElementById('main-canvas');canvasElement.classList.remove('cursor-brush','cursor-bucket','cursor-text');if(tool==='brush'){canvasElement.classList.add('cursor-brush');}else if(tool==='bucket'){canvasElement.classList.add('cursor-bucket');}else if(tool==='text'){canvasElement.classList.add('cursor-text');}}function mostrarEditorTexto(e){const editor=document.getElementById('text-editor');const textarea=document.getElementById('text-input');const rect=canvas.getBoundingClientRect();const clickX=(e.clientX-rect.left)*(canvas.width/rect.width);const clickY=(e.clientY-rect.top)*(canvas.height/rect.height);const alturaControles=45;textEditorPosition.x=clickX;textEditorPosition.y=clickY+alturaControles;currentRotationText=0;currentFontSizeText=30;textarea.value="";actualizarAparienciaEditor();editor.style.left=`${e.clientX}px`;editor.style.top=`${e.clientY}px`;editor.classList.remove('text-editor-hidden');setTimeout(()=>textarea.focus(),10);}function changeFontSizeText(delta){currentFontSizeText+=delta;if(currentFontSizeText<10)currentFontSizeText=10;actualizarAparienciaEditor();}function rotateText(){currentRotationText-=5;actualizarAparienciaEditor();}function actualizarAparienciaEditor(){const textarea=document.getElementById('text-input');textarea.style.fontSize=`${currentFontSizeText}px`;textarea.style.transformOrigin="top left";textarea.style.transform=`rotate(${currentRotationText}deg)`;textarea.style.color=color;textarea.style.height=`${currentFontSizeText*5.5}px`;textarea.style.width=`${currentFontSizeText*10}px`;textarea.style.backgroundColor="transparent";}function applyText(){const textarea=document.getElementById('text-input');const texto=textarea.value;if(!texto)return closeEditor();ctx.save();ctx.translate(textEditorPosition.x,textEditorPosition.y);ctx.rotate((currentRotationText*Math.PI)/180);ctx.fillStyle=color;ctx.font=`bold ${currentFontSizeText}px "Comic Sans MS","Marker Felt",sans-serif`;ctx.textBaseline="top";ctx.textAlign="left";const lineas=texto.split('\n');const interlineado=1.2;lineas.forEach((linea,index)=>{ctx.fillText(linea,0,index*(currentFontSizeText*interlineado));});ctx.restore();closeEditor();}function closeEditor(){document.getElementById('text-editor').classList.add('text-editor-hidden');}function transicionPagina(direccion){sonar(sonidoPagina);const canvas=document.getElementById('main-canvas');const overlay=document.getElementById('page-overlay');const dataURL=canvas.toDataURL();overlay.style.backgroundImage=`url(${dataURL})`;overlay.classList.remove('page-overlay-hidden','shrink-to-left','shrink-to-right');if(direccion==='siguiente'){siguienteDibujo();}else{anteriorDibujo();}setTimeout(()=>{if(direccion==='siguiente'){overlay.classList.add('shrink-to-left');}else{overlay.classList.add('shrink-to-right');}},222);setTimeout(()=>{overlay.classList.add('page-overlay-hidden');},650);}async function compartirArteNativo(){const canvas=document.getElementById('main-canvas');canvas.style.filter="brightness(2)";setTimeout(()=>canvas.style.filter="none",150);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));const archivo=new File([blob],'mi-dibujo-mario.png',{type:'image/png'});if(navigator.share && navigator.canShare({files:[archivo]})){try{await navigator.share({files:[archivo],title:'¡Mira mi dibujo!',text:'Pinté este Mario en mi cuaderno digital 🎨'});}catch(err){console.log("El usuario canceló o hubo un error:",err);}}else{abrirModalCompartir();}}function abrirModalCompartir(){const urlApp=window.location.href;const qrUrl=`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(urlApp)}`;const modalHTML=`<div id="custom-share-modal" class="modal-overlay"><div class="modal-content"><h3>¡Comparte tu arte! 🎨</h3><p>Para enviar este dibujo directamente a WhatsApp o Instagram,escanea este código con tu celular:</p><img src="${qrUrl}" alt="Código QR para compartir"><hr><p>O si prefieres,guárdalo en tu computadora para compartirlo:</p><button onclick="downloadImage();cerrarModal();">💾 Descargar Dibujo</button><button onclick="cerrarModal();" class="btn-cerrar">Cerrar</button></div></div>`;document.body.insertAdjacentHTML('beforeend',modalHTML);}function cerrarModal(){const modal=document.getElementById('custom-share-modal');if(modal)modal.remove();}function mostrarBotonCompartir(){alert("entra mostrarbot");if(!haPintado){alert("no hapintado");const btn=document.querySelector('.share-btn-floating');if(btn){btn.classList.add('visible');haPintado=true;}}}function siguienteDibujo(){indiceActual=(indiceActual+1)% pdfActual.length;cargarDibujo(pdfActual[indiceActual]);}function configurarPDFDesdeURL(){const params=new URLSearchParams(window.location.search);const nombrePDF=params.get("pdf");if(nombrePDF && pdfs[nombrePDF]){pdfActual=pdfs[nombrePDF];}else{alert("El url no está bien formado,avisa a tu proveedor del enlace. Te redirigimos al canal donde puedes adquirir esta App para colorear tus PDFs");}}
